ctx, cancel := context.WithCancel(r.Context())
defer cancel()                              // owner releases the child

go func() {
    select {
    case <-ctx.Done():                      // safe point
        return                              // ctx.Err() says why
    case item := <-work:
        process(ctx, item)
    }
}()

ctx, cancel := context.WithTimeoutCause(r.Context(), 2*time.Second,
    errors.New("upstream budget exhausted"))
defer cancel()

if err := doWork(ctx); err != nil {
    if errors.Is(err, context.DeadlineExceeded) {
        log.Printf("cancelled: %v", context.Cause(ctx))   // the recorded reason
    }
    return err
}

